const zeroLevelsOutsideLocation = `-- name: ZeroLevelsOutsideLocation :execrows
UPDATE inventory_levels
SET quantity = 0, updated_at = NOW()
WHERE location_id <> $1
  AND quantity <> 0
`

// Clears stock parked at every OTHER location, so a flat -> multi flip lands the whole quantity in
// one place instead of summing with whatever the pre-flat era left behind
func (q *Queries) ZeroLevelsOutsideLocation(ctx context.Context, locationID uuid.UUID) (int64, error) {
	result, err := q.db.ExecContext(ctx, zeroLevelsOutsideLocation, locationID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}
